def count_missing(shares: dict[str, float | None]) -> int:
    """Number of brands with no share recorded."""
    missing = 0
    for brand, share in shares.items():
        if not share:
            missing += 1
    return missing

exercises.fix_solution:
def count_missing(shares: dict[str, float | None]) -> int:
    """Number of brands with no share recorded."""
    missing = 0
    for brand, share in shares.items():
        if share is None:
            missing += 1
    return missing
